<?php
declare(strict_types=1); admin_required(); $route=rtrim($path,'/');
function fpage(string $title,string $active):void{?><!doctype html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=$title?> | Checkout 360BH</title><link rel="stylesheet" href="/assets/admin.css?v=20260924"><style>.actions{white-space:nowrap}.actions a,.actions button{display:inline-block;border:0;background:none;cursor:pointer;text-decoration:none;font-size:18px;margin-right:7px}.danger{color:#b42318}</style></head><body><div class="admin-shell"><aside class="sidebar"><div class="brand">360BH<small>Checkout financeiro</small></div><nav class="nav"><a class="<?=$active==='dashboard'?'active':''?>" href="/admin">■ Visão geral</a><a href="/admin/services">⚙ Serviços</a><a href="/admin/customers">👤 Clientes</a><a href="/admin/links/new">＋ Criar cobrança</a></nav><div class="sidebar-footer"><a href="/admin/logout">Sair da conta</a></div></aside><section class="main"><header class="topbar"><button class="menu-toggle" onclick="document.querySelector('.sidebar').classList.toggle('open')">☰</button><h1><?=$title?></h1><a class="btn btn-light" href="/admin/links/new">Novo link</a></header><main class="content"><?php}
function fend():void{?></main></section></div></body></html><?php}
if($route==='/admin/links/delete'&&$method==='POST'){csrf_check();db()->prepare("UPDATE payment_links SET status='CANCELED' WHERE id=?")->execute([(int)$_POST['id']]);header('Location: /admin',true,303);exit;}
if($route==='/admin/links/copy'&&$method==='GET'){$id=(int)($_GET['id']??0);$raw=public_token();$q=db()->prepare('SELECT id FROM payment_links WHERE id=?');$q->execute([$id]);if(!$q->fetch()){http_response_code(404);exit('Link não encontrado');}db()->prepare('UPDATE payment_links SET token_hash=?,status=\'ACTIVE\' WHERE id=?')->execute([token_hash($raw),$id]);$url=rtrim((string)envv('APP_URL'),' /').'/pagar/'.$raw;fpage('Link copiado','dashboard');?><section class="panel"><div class="notice">Link público gerado.</div><input id="url" value="<?=htmlspecialchars($url)?>" readonly><button class="btn" onclick="navigator.clipboard.writeText(document.getElementById('url').value)">Copiar link</button><a class="btn btn-light" href="/admin">Voltar</a></section><?php fend();exit;}
if($route==='/admin'){try{$pdo=db();$links=$pdo->query('SELECT id,description,amount_cents,payment_type,status FROM payment_links ORDER BY id DESC LIMIT 50')->fetchAll();$total=(int)$pdo->query('SELECT COUNT(*) FROM payment_links')->fetchColumn();$active=(int)$pdo->query("SELECT COUNT(*) FROM payment_links WHERE status='ACTIVE'")->fetchColumn();$paid=(int)$pdo->query("SELECT COUNT(*) FROM payment_intents WHERE status='PAID'")->fetchColumn();}catch(Throwable $e){error_log('[admin] '.$e->getMessage());$links=[];$total=$active=$paid=0;}fpage('Visão geral','dashboard');?><div class="welcome"><h2>Olá, administrador</h2><p class="muted">Acompanhe seus links e cobranças em um só lugar.</p></div><section class="cards"><div class="card"><div class="card-label">Links criados</div><div class="card-value"><?=$total?></div></div><div class="card"><div class="card-label">Links ativos</div><div class="card-value"><?=$active?></div></div><div class="card"><div class="card-label">Pagamentos aprovados</div><div class="card-value"><?=$paid?></div></div><div class="card"><div class="card-label">Gateway</div><div class="card-value" style="font-size:20px">Asaas</div></div></section><section class="panel"><div class="panel-header"><h2>Links de cobrança recentes</h2><a class="btn" href="/admin/links/new">Criar link</a></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>Descrição</th><th>Valor</th><th>Tipo</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php foreach($links as $l):?><tr><td>#<?=$l['id']?></td><td><?=htmlspecialchars($l['description'])?></td><td>R$ <?=money((int)$l['amount_cents'])?></td><td><?=htmlspecialchars($l['payment_type'])?></td><td><span class="status status-<?=strtolower($l['status'])?>"><?=htmlspecialchars($l['status'])?></span></td><td class="actions"><a href="/admin/links/new?edit=<?=$l['id']?>" title="Editar">✏️</a><a href="/admin/links/copy?id=<?=$l['id']?>" title="Copiar link">🔗</a><?php if($l['status']==='ACTIVE'):?><form method="post" action="/admin/links/delete" style="display:inline" onsubmit="return confirm('Cancelar este link?')"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$l['id']?>"><button class="danger" title="Excluir">🗑️</button></form><?php endif;?></td></tr><?php endforeach;if(!$links):?><tr><td colspan="6" class="muted">Nenhum link criado ainda.</td></tr><?php endif;?></tbody></table></div></section><?php fend();exit;}
if($route==='/admin/services'||$route==='/admin/customers'){fpage($route==='/admin/services'?'Serviços':'Clientes',$route==='/admin/services'?'services':'customers');?><section class="panel"><h2><?= $route==='/admin/services'?'Serviços':'Clientes'?></h2><p class="muted">Área disponível para gerenciamento.</p></section><?php fend();exit;}http_response_code(404);echo'Not found';
